<?php
declare(strict_types=1);
require_once __DIR__.'/flow.php';
function lc_closure_gate():void{if(crm_query("SELECT state FROM nd_schema_migrations WHERE version='017_lifecycle_closure'")->fetchColumn()!=='applied')crm_fail(503,'Завершение цикла ещё не подготовлено.');}
function lc_schedule_input(array $rows):string{return lc_json(array_map(fn($r)=>['label'=>$r['label'],'amount'=>bill_decimal((int)$r['amount_minor']),'due_on'=>$r['due_on'],'gate'=>$r['gate'],'stage_id'=>$r['stage_id']===null?null:(int)$r['stage_id']],$rows));}
function lc_downstream_document_source(array $a,array $t,array $p,array $order,array $d):array{
 lc_closure_gate();$f=lc_flow($a,(int)$order['id'],true);if(!$f['agreement_binding_id'])crm_fail(409,'Нет согласованных исходных условий.');$agreement=lc_binding($a,(int)$f['agreement_binding_id']);$in=json_decode($agreement['input_snapshot'],true,512,JSON_THROW_ON_ERROR);$fields=array_intersect_key($in['fields'],lc_input_labels());$fields['payment_schedule']=lc_schedule_input($in['payment_schedule']);$evidence=['agreement_id'=>(int)$agreement['id'],'agreement_hash'=>$agreement['generated_hash'],'kind'=>$t['kind']];$quotation=(int)$in['quotation']['id'];
 if($t['kind']==='change_order'){$change=crm_query('SELECT * FROM nd_lc_scope_changes WHERE id=? AND order_id=? FOR UPDATE',[cc_id($d['change_id']??null),$order['id']])->fetch();if(!$change||$change['owner_decision']!=='ACCEPT'||$change['client_decision']!=='ACCEPT'||$change['applied_at']!==null)crm_fail(409,'Нужны два отдельных решения по точной редакции изменения.');$proposal=json_decode($change['proposal_json'],true,512,JSON_THROW_ON_ERROR);$fields['deliverables']=$proposal['revised_scope'];$fields['milestones']=$proposal['schedule_effect'];$fields['payment_schedule']=cc_text($d,'revised_payment_schedule',20000);$quotation=(int)$proposal['quotation_id'];$evidence['change_id']=(int)$change['id'];$evidence['change_hash']=$change['checksum'];$evidence['previous_price_minor']=(int)$proposal['old_total_minor'];$evidence['revised_price_minor']=(int)$proposal['new_total_minor'];}
 elseif($t['kind']==='acceptance'){if($f['acceptance_state']!=='ACCEPTED'||!$f['final_manifest'])crm_fail(409,'Акт формируется после явной приёмки фактически завершённого состава.');$manifest=lc_manifest($f);$actual=lc_json(['agreement_id'=>(int)$f['agreement_binding_id'],'milestones'=>$manifest]);if(!hash_equals($f['final_hash'],hash('sha256',$actual)))crm_fail(409,'После приёмки изменилась версия результата. Нужна новая приёмка.');$fields['deliverables']=implode("\n",array_map(fn($m)=>$m['title'].' · версия '.$m['revision_number'].' · '.$m['evidence']['deliverables'].' · публикация '.$m['evidence']['deployment_url'].' · ревизия '.$m['evidence']['published_revision'].' · SHA256 '.$m['checksum'],$manifest));$evidence['final_manifest_hash']=$f['final_hash'];$evidence['milestones']=$manifest;}
 elseif($t['kind']==='handover'){if(!in_array($f['delivery_state'],['HANDOVER_PREPARED','HANDED_OVER'],true)||!$f['handover_hash'])crm_fail(409,'Сначала подготовьте и проверьте реальный состав передачи.');$items=crm_query("SELECT id,title,details,file_id,verification_reason FROM nd_lc_obligations WHERE order_id=? AND kind='HANDOVER' ORDER BY id",[$order['id']])->fetchAll();$fields['handover_terms']=implode("\n",array_map(fn($i)=>$i['title'].': '.$i['details'].($i['file_id']?' · файл №'.$i['file_id']:''),$items));$evidence['handover_hash']=$f['handover_hash'];$evidence['items']=$items;}
 elseif($t['kind']==='support'){if(!$f['support_terms'])crm_fail(409,'Сначала проверьте и зафиксируйте реальную поддержку.');$fields['support_terms']=$f['support_terms'].($f['support_start']?' · '.$f['support_start'].' — '.$f['support_end']:'');$evidence['support_start']=$f['support_start'];$evidence['support_end']=$f['support_end'];}else crm_fail(422,'Неподдерживаемый завершающий документ.');
 return ['fields'=>$fields,'quotation_id'=>$quotation,'evidence'=>$evidence];
}
function lc_bind_final_document(array $a,array $f,string $kind,array $d):array{
 cc_owner($a);lc_closure_gate();$b=lc_binding($a,cc_id($d['binding_id']??null));if((int)$b['order_id']!==(int)$f['order_id']||$b['kind']!==$kind)crm_fail(422,'Выберите документ этого заказа нужного типа.');$in=json_decode($b['input_snapshot'],true,512,JSON_THROW_ON_ERROR);$source=$in['lifecycle_source']??[];
 if($kind==='acceptance'){if($b['state']!=='AGREED'||($source['final_manifest_hash']??null)!==$f['final_hash']||$f['acceptance_state']!=='ACCEPTED')crm_fail(409,'Нужен проверенный подписанный акт точного принятого результата.');$column='acceptance_binding_id';}elseif($kind==='handover'){if(!in_array($b['state'],['SENT','SIGNED_COPY_SUBMITTED','AGREED'],true)||($source['handover_hash']??null)!==$f['handover_hash'])crm_fail(409,'Нужен проверенный и открытый клиенту перечень фактической передачи.');$column='handover_binding_id';}else crm_fail(422,'Тип документа не поддерживается.');
 crm_query('INSERT INTO nd_lc_closure_records(order_id,'.$column.') VALUES (?,?) ON DUPLICATE KEY UPDATE '.$column.'=VALUES('.$column.'),version=version+1',[$f['order_id'],$b['id']]);lc_audit($a,'order',(int)$f['order_id'],'final_document_bound',(int)$f['version'],['binding_id'=>$b['id'],'kind'=>$kind,'hash'=>$b['generated_hash']]);return ['ok'=>true,'id'=>(int)$f['order_id']];
}
function lc_closure_obligations(array $f,array $a):array{
 $missing=[];if($f['acceptance_state']!=='ACCEPTED')$missing[]='Нет явной приёмки итоговой версии.';$payment=lc_financial_facets($f);if($payment['state']!=='SETTLED')$missing[]='Финансовый расчёт не завершён или требуется сверка.';if($f['delivery_state']!=='HANDED_OVER')$missing[]='Передача результата не подтверждена клиентом.';if(!$f['support_terms'])$missing[]='Не зафиксированы условия поддержки или её отсутствие.';
 $record=crm_query('SELECT * FROM nd_lc_closure_records WHERE order_id=?',[$f['order_id']])->fetch();if(!$record||!$record['acceptance_binding_id'])$missing[]='Нет проверенного подписанного акта приёмки.';if(!$record||!$record['handover_binding_id'])$missing[]='Не закреплён перечень фактически переданного результата.';
 if($record&&$record['acceptance_binding_id']){$b=lc_binding($a,(int)$record['acceptance_binding_id']);cc_revision($a,(int)$b['revision_id']);$input=json_decode($b['input_snapshot'],true);if($b['state']!=='AGREED'||($input['lifecycle_source']['final_manifest_hash']??null)!==$f['final_hash'])$missing[]='Подписанный акт относится к прежней версии результата.';}
 if($record&&$record['handover_binding_id']){$b=lc_binding($a,(int)$record['handover_binding_id']);cc_revision($a,(int)$b['revision_id']);$input=json_decode($b['input_snapshot'],true);if(($input['lifecycle_source']['handover_hash']??null)!==$f['handover_hash'])$missing[]='Перечень передачи относится к другой версии.';}
 if(crm_query("SELECT id FROM nd_lc_receipt_tasks WHERE order_id=? AND state<>'TRANSMISSION_RECORDED' LIMIT 1",[$f['order_id']])->fetchColumn())$missing[]='Есть невыполненные задачи официальных чеков, передачи или корректировки.';
 if(crm_query("SELECT r.id FROM nd_lc_feedback r JOIN nd_lc_milestone_versions v ON v.id=r.milestone_version_id WHERE v.order_id=? AND r.state='OPEN' LIMIT 1",[$f['order_id']])->fetchColumn())$missing[]='Есть неразрешённые замечания.';
 if(crm_query("SELECT c.id FROM nd_lc_payment_claims c JOIN nd_invoices i ON i.id=c.invoice_id WHERE i.order_id=? AND c.state='REPORTED' LIMIT 1",[$f['order_id']])->fetchColumn())$missing[]='Есть несверенные сообщения об оплате.';
 if(crm_query("SELECT id FROM nd_lc_scope_changes WHERE order_id=? AND applied_at IS NULL AND COALESCE(owner_decision,'')<>'REJECT' AND COALESCE(client_decision,'')<>'REJECT' LIMIT 1",[$f['order_id']])->fetchColumn())$missing[]='Есть незавершённое согласование изменения объёма.';
 if(crm_query("SELECT id FROM nd_lc_obligations WHERE order_id=? AND required=1 AND state NOT IN ('VERIFIED','NOT_APPLICABLE') LIMIT 1",[$f['order_id']])->fetchColumn())$missing[]='Не все обязательные материалы или пункты передачи проверены.';
 if(in_array($f['case_state'],['PAUSED','DISPUTED'],true))$missing[]='Не закрыта пауза или спор.';return $missing;
}
function lc_close_order(array $a,array $f,array $d):array{
 cc_owner($a);lc_closure_gate();if($f['case_state']==='CLOSED'||($d['confirm']??false)!==true)crm_fail(409,'Заказ уже закрыт или решение не подтверждено.');$missing=lc_closure_obligations($f,$a);$override=($d['override']??false)===true;$reason=cc_text($d,'reason',5000);if($missing&&!$override)crm_fail(409,'Закрытие заблокировано: '.implode(' ',$missing));if($missing&&($d['acknowledge_remaining_obligations']??false)!==true)crm_fail(422,'Исключение не отменяет банковские, налоговые или договорные обязательства. Подтвердите понимание и укажите основание.');$snapshot=['flow_version'=>(int)$f['version'],'final_hash'=>$f['final_hash'],'handover_hash'=>$f['handover_hash'],'payment'=>lc_financial_facets($f),'support'=>['terms'=>$f['support_terms'],'start'=>$f['support_start'],'end'=>$f['support_end']],'reason'=>$reason];
 crm_query('INSERT INTO nd_lc_closure_records(order_id,closure_snapshot,unresolved_snapshot,override_reason,closed_by,closed_at) VALUES (?,?,?,?,1,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE closure_snapshot=VALUES(closure_snapshot),unresolved_snapshot=VALUES(unresolved_snapshot),override_reason=VALUES(override_reason),closed_by=1,closed_at=UTC_TIMESTAMP(),version=version+1',[$f['order_id'],lc_json($snapshot),lc_json($missing),$missing?$reason:null]);crm_query("UPDATE nd_orders SET status='completed',completed_at=UTC_TIMESTAMP(),version=version+1 WHERE id=?",[$f['order_id']]);crm_query("UPDATE nd_projects SET status='completed',completed_at=UTC_TIMESTAMP(),version=version+1 WHERE id=?",[$f['project_id']]);return lc_flow_save($a,$f,$missing?'closed_with_explicit_override':'closed_verified',['case_state'=>'CLOSED'],['reason'=>$reason,'remaining_obligations'=>$missing,'receipt_tasks_erased'=>false,'signature_fabricated'=>false]);
}
function lc_apply_change(array $a,array $f,array $d):array{
 cc_owner($a);lc_closure_gate();lc_flow_active($f);if(($d['confirm']??false)!==true)crm_fail(422,'Подтвердите применение точной подписанной редакции и сверку реальных денег.');$id=cc_id($d['change_id']??null);$change=crm_query('SELECT * FROM nd_lc_scope_changes WHERE id=? AND order_id=? FOR UPDATE',[$id,$f['order_id']])->fetch();if(!$change||$change['owner_decision']!=='ACCEPT'||$change['client_decision']!=='ACCEPT'||$change['applied_at']!==null)crm_fail(409,'Нужны два отдельных решения по ещё не применённому изменению.');$b=lc_binding($a,cc_id($d['binding_id']??null),true);cc_revision($a,(int)$b['revision_id']);$in=json_decode($b['input_snapshot'],true,512,JSON_THROW_ON_ERROR);$src=$in['lifecycle_source']??[];$proposal=json_decode($change['proposal_json'],true,512,JSON_THROW_ON_ERROR);if($b['state']!=='AGREED'||$b['kind']!=='change_order'||(int)$b['order_id']!==(int)$f['order_id']||($src['change_id']??null)!==$id||($src['change_hash']??null)!==$change['checksum']||($src['agreement_id']??null)!==(int)$f['agreement_binding_id']||(int)$in['quotation']['id']!==(int)$proposal['quotation_id'])crm_fail(409,'Подписанный документ не соответствует точному принятому изменению и исходному договору.');
 $order=crm_record('orders',(int)$f['order_id'],true);$old=bill_minor($order['total_amount']);$new=(int)$proposal['new_total_minor'];if($old!==(int)$proposal['old_total_minor']||$new!==bill_minor($in['fields']['price']))crm_fail(409,'Исходная или новая цена изменилась. Нужно новое согласование.');$template=lc_template(cc_id($d['invoice_template_id']??null),true);if($template['kind']!=='invoice'||$template['state']!=='APPROVED')crm_fail(409,'Нужен действующий одобренный шаблон запроса оплаты.');
 $invoices=crm_query("SELECT i.* FROM nd_invoices i JOIN nd_lc_schedule_entries s ON s.invoice_id=i.id WHERE s.order_id=? AND i.state='issued' ORDER BY i.id FOR UPDATE",[$f['order_id']])->fetchAll();$net=0;$snapshots=[];foreach($invoices as $invoice){$balance=bill_balance($invoice);$net+=$balance['net_minor'];$snapshots[]=['invoice_id'=>(int)$invoice['id'],'snapshot_hash'=>$invoice['snapshot_hash'],'balance'=>$balance];if(crm_query("SELECT id FROM nd_payment_attempts WHERE invoice_id=? AND state IN ('creating','pending') LIMIT 1",[$invoice['id']])->fetchColumn())crm_fail(409,'Сначала завершите сверку незавершённого платёжного процесса.');}
 if($net>$new)crm_fail(409,'Подтверждённые деньги превышают новую цену. Сначала нужен фактически выполненный и отдельно проверенный возврат. Сайт его не инициирует.');if(crm_query("SELECT c.id FROM nd_lc_payment_claims c JOIN nd_invoices i ON i.id=c.invoice_id WHERE i.order_id=? AND c.state='REPORTED' LIMIT 1",[$f['order_id']])->fetchColumn())crm_fail(409,'Сначала сверьте все сообщения клиента об оплате.');
 foreach($invoices as $invoice){$balance=bill_balance($invoice);if($balance['outstanding_minor']>0){$key=hash('sha256','lc-change:'.$id.':invoice:'.$invoice['id']);crm_query('INSERT INTO nd_invoice_adjustments(invoice_id,amount_minor,reason,request_key) VALUES (?,?,?,?)',[$invoice['id'],$balance['outstanding_minor'],'Заменено подписанным изменением №'.$id,$key]);crm_query('UPDATE nd_invoices SET version=version+1 WHERE id=?',[$invoice['id']]);}}
 $offset=(int)crm_query('SELECT COALESCE(MAX(position),0) FROM nd_lc_schedule_entries WHERE order_id=?',[$f['order_id']])->fetchColumn();$newIds=lc_issue_schedule_entries($a,$order,$b,$in,$in['payment_schedule'],$template,$offset,$net);$reason=cc_text($d,'reason',4000);crm_query('INSERT INTO nd_lc_change_applications(change_id,signed_binding_id,previous_binding_id,previous_price_minor,revised_price_minor,credited_actual_income_minor,invoice_snapshot,new_invoice_ids,applied_by) VALUES (?,?,?,?,?,?,?,?,1)',[$id,$b['id'],$f['agreement_binding_id'],$old,$new,$net,lc_json($snapshots),lc_json($newIds)]);crm_query('UPDATE nd_lc_scope_changes SET agreement_binding_id=?,applied_at=UTC_TIMESTAMP(),version=version+1 WHERE id=?',[$b['id'],$id]);
 $due=$proposal['revised_due_on']??null;crm_query('UPDATE nd_orders SET total_amount=?,due_on=COALESCE(?,due_on),version=version+1 WHERE id=?',[bill_decimal($new),$due,$f['order_id']]);crm_query('UPDATE nd_projects SET due_on=COALESCE(?,due_on),version=version+1 WHERE id=?',[$due,$f['project_id']]);if($new===0&&$net===0)lc_audit($a,'order',(int)$f['order_id'],'zero_price_schedule_confirmed',(int)$f['version'],['binding_id'=>$b['id'],'hash'=>$b['generated_hash']]);return lc_flow_save($a,$f,'signed_scope_change_applied',['agreement_binding_id'=>(int)$b['id'],'quotation_id'=>(int)$proposal['quotation_id'],'acceptance_state'=>'PENDING','delivery_state'=>'OWNER_REVIEW','final_manifest'=>null,'final_hash'=>null,'handover_hash'=>null],['change_id'=>$id,'previous_binding_id'=>$f['agreement_binding_id'],'new_binding_id'=>$b['id'],'prior_actual_income_credited_minor'=>$net,'new_invoice_ids'=>$newIds,'new_income_created'=>false,'reason'=>$reason]);
}
